# build_supplemental_dicts.jl
#
# Regenerates `notebooks/supplemental/all_temp_level_dict.jld2` — the per-energy-level D_KL
# sweep used by the nearest-neighbor Ising appendix figures (`supp_fig_working-new.pdf`, and the
# per-level panel of `fig4-working-latest.pdf`).
#
# IMPORTANT: this data is generated by an INDEPENDENT re-sampling + re-fitting sweep (draw fresh
# samples from the true 4x4 Ising model, fit by exact MLE, compute per-level D_KLs). It is NOT a
# decomposition of the raw sweeps on Hugging Face, so it cannot be regenerated from them — the
# committed `all_temp_level_dict.jld2` IS the exact data used in the paper. Re-running this script
# produces STATISTICALLY EQUIVALENT (not identical) data, because the samples are random.
#
# Adapted from proteins/temp_analysis/dkl_per_lev_M_T.jl; reuses temp-tune/src/nearest_neighbor_ising.jl.
#
# Usage:
#   julia --project=. scripts/build_supplemental_dicts.jl              # full sweep (slow: 8 T x 13 M x 50 reps)
#   SMOKE=true julia --project=. scripts/build_supplemental_dicts.jl   # tiny smoke test

using DrWatson
@quickactivate "temp-tune"
# nearest_neighbor_ising.jl assumes the caller has imported these (it has no `using` of its own).
using JLD2, Statistics, LinearAlgebra, StatsBase, Random, Distributions, Parameters, Flux, Printf, Graphs, SpinModels
include(srcdir("nearest_neighbor_ising.jl"))   # init_2dNN, ExactMLBuffer, Energy2spinBuffer,
                                               # get_level_index_dict, get_true_prob, drawsamples_exact,
                                               # init_Jfit, ml_fit_Jij, get_pemp, get_dkl, FitOptions2spinExact

# Not in src — small helper, ported from dkl_per_lev_M_T.jl:
function get_dkl_per_level_direct(p1, p2, level_index_dict)
    dkls_per_lev = zeros(length(level_index_dict))
    for l in 1:length(level_index_dict)
        g_idx = level_index_dict[l]
        dkls_per_lev[l] = get_dkl(p1[g_idx], p2[g_idx])
    end
    return dkls_per_lev
end

# --- sweep configuration (matches the paper's Appendix-D per-level sweep) ---
all_tts = [2.3, 2.4, 2.6, 2.8, 3.2, 3.6, 4.0, 4.4]
Mss     = Int.(round.(10 .^ collect(1:0.2:4)))[4:end]   # 13 training-set sizes
nreps   = 50

SMOKE = get(ENV, "SMOKE", "false") == "true"
if SMOKE
    all_tts = [2.3]; Mss = Mss[1:2]; nreps = 2
    @info "SMOKE test: 1 temperature, 2 M values, 2 reps"
end

θ, Jij = init_2dNN(4, 4)
fit_opts = FitOptions2spinExact(Jij; learning_rate=0.01, relTol=1e-5, max_iter=10000, showevery=10000)
ml_exact_buffer = ExactMLBuffer(Jij)
level_idcs = get_level_index_dict(Jij, ml_exact_buffer, Energy2spinBuffer(ml_exact_buffer.all_states, Jij))
nlev = length(level_idcs)

all_temp_level_dict = Dict()
for temp in all_tts
    println("T = $temp")
    emp_q = zeros(nlev, length(Mss), nreps)
    emp_p = similar(emp_q)
    q_p   = similar(emp_q)
    ptrue = get_true_prob(ml_exact_buffer, Jij / temp)
    for (m, M) in enumerate(Mss)
        for r in 1:nreps
            zz = drawsamples_exact(ml_exact_buffer, Jij, temp, M)
            Jfit, _, dkl_per_l = ml_fit_Jij(init_Jfit(size(Jij, 1)), zz, fit_opts, ml_exact_buffer;
                                            level_indices=level_idcs, silent=true)
            emp_q[:, m, r] = dkl_per_l
            pemp = get_pemp(zz, ml_exact_buffer.all_states)
            qfit = get_true_prob(ml_exact_buffer, Jfit / 1.0)
            emp_p[:, m, r] = get_dkl_per_level_direct(pemp, ptrue, level_idcs)
            q_p[:, m, r]   = get_dkl_per_level_direct(qfit, ptrue, level_idcs)
        end
    end
    all_temp_level_dict[temp] = Dict(
        :all_dkl_per_lev_emp_q => emp_q,
        :all_dkl_per_lev_emp_p => emp_p,
        :all_dkl_per_lev_q_p   => q_p,
    )
end

out = projectdir("notebooks", "supplemental",
                 SMOKE ? "all_temp_level_dict_SMOKE.jld2" : "all_temp_level_dict.jld2")
jldsave(out; data = all_temp_level_dict)
println("saved -> ", out, "   temps: ", sort(collect(keys(all_temp_level_dict))))
